1	package tracepath
2	
3	import (
4		"crypto/sha256"
5		"encoding/json"
6		"fmt"
7		"net/url"
8		"sort"
9		"strconv"
10		"strings"
11		"time"
12	)
13	
14	// Service implements the TracePath contract on top of a Store. It owns span
15	// ingestion, trace reassembly, critical path analysis, error propagation
16	// marking and the service dependency graph.
17	type Service struct {
18		store *Store
19		clock func() time.Time
20	}
21	
22	// NewService wires a store and an injectable clock.
23	func NewService(store *Store, clock func() time.Time) (*Service, error) {
24		if store == nil {
25			return nil, InternalError("service requires a store")
26		}
27		if clock == nil {
28			clock = time.Now
29		}
30		return &Service{store: store, clock: clock}, nil
31	}
32	
33	func (s *Service) now() string {
34		return s.clock().UTC().Format(idLayout)
35	}
36	
37	// validateIdempotencyKey enforces the presence and length rules every
38	// idempotent operation shares.
39	func validateIdempotencyKey(key string) error {
40		if key == "" {
41			return ValidationError("Idempotency-Key header is required")
42		}
43		if len(key) > 200 {
44			return ValidationError("Idempotency-Key must be at most 200 characters")
45		}
46		return nil
47	}
48	
49	// runIdempotent executes action at most once per key. The first response is
50	// re-rendered from committed state for every later request that carries the
51	// same key and the same resource identity, so a replay is byte-identical by
52	// construction. Reusing a key for another operation, or for another resource,
53	// is a conflict.
54	func (s *Service) runIdempotent(key string, operation string, identity string, action func(state *State) (any, error)) (any, error) {
55		if err := validateIdempotencyKey(key); err != nil {
56			return nil, err
57		}
58		var response any
59		err := s.store.Update(func(state *State) error {
60			if record, found := state.Idempotency[key]; found {
61				if record.Operation != operation {
62					return ConflictError("idempotency key was already used for another operation")
63				}
64				if record.Identity != identity {
65					return ConflictError("idempotency key was already used for resource %s", record.Identity)
66				}
67				response = identity
68				return nil
69			}
70			value, err := action(state)
71			if err != nil {
72				return err
73			}
74			state.Idempotency[key] = &IdempotencyRecord{
75				Key:       key,
76				Operation: operation,
77				Identity:  identity,
78				CreatedAt: s.now(),
79			}
80			response = value
81			return nil
82		})
83		if err != nil {
84			return nil, err
85		}
86		return response, nil
87	}
88	
89	// spanResponse is the public projection of one ingested span.
90	type spanResponse struct {
91		TraceID    string            `json:"trace_id"`
92		SpanID     string            `json:"span_id"`
93		ParentID   *string           `json:"parent_id"`
94		Service    string            `json:"service"`
95		Operation  string            `json:"operation"`
96		Kind       string            `json:"kind"`
97		StartTime  string            `json:"start_time"`
98		DurationNS int64             `json:"duration_ns"`
99		Status     string            `json:"status"`
100		Attributes map[string]string `json:"attributes"`
101		Accepted   bool              `json:"accepted"`
102		SpanCount  int               `json:"span_count"`
103		Complete   bool              `json:"complete"`
104		Valid      bool              `json:"valid"`
105		Violations []Validation      `json:"violations"`
106	}
107	
108	// renderSpan projects one stored span onto its public projection. The identity
109	// of the projected span is returned as well.
110	func renderSpan(state *State, traceID string, spanID string) (any, error) {
111		spans, found := state.Spans[traceID]
112		if !found {
113			return nil, InternalError("trace %s disappeared during ingestion", traceID)
114		}
115		span, found := spans[spanID]
116		if !found {
117			return nil, InternalError("span %s of trace %s disappeared during ingestion", spanID, traceID)
118		}
119		trace := assembleTrace(traceID, spans)
120		declared := trace.SpanCount
121		if trace.RootSpanCount != 0 {
122			declared = trace.RootSpanCount
123		}
124		response := &spanResponse{
125			TraceID:    span.TraceID,
126			SpanID:     span.SpanID,
127			ParentID:   span.ParentID,
128			Service:    span.Service,
129			Operation:  span.Operation,
130			Kind:       span.Kind,
131			StartTime:  span.StartTime,
132			DurationNS: span.DurationNS,
133			Status:     span.Status,
134			Attributes: map[string]string{},
135			Accepted:   true,
136			SpanCount:  declared,
137			Complete:   trace.Complete,
138			Valid:      trace.Valid,
139			Violations: publicViolations(trace.Violations),
140		}
141		for attribute, value := range span.Attributes {
142			response.Attributes[attribute] = value
143		}
144		return response, nil
145	}
146	
147	// decodeSpanInput strictly decodes one span document and runs every check that
148	// does not need the stored state. It returns the parsed start instant and the
149	// trimmed identifiers, exactly as single-span ingestion uses them.
150	func decodeSpanInput(body []byte) (*SpanInput, time.Time, string, string, error) {
151		var input SpanInput
152		if err := decodeObject(body, &input); err != nil {
153			return nil, time.Time{}, "", "", err
154		}
155		start, err := validateSpanInput(&input)
156		if err != nil {
157			return nil, time.Time{}, "", "", err
158		}
159		spanID, err := validateIdentifier(input.SpanID, "span_id")
160		if err != nil {
161			return nil, time.Time{}, "", "", err
162		}
163		traceID, err := validateIdentifier(input.TraceID, "trace_id")
164		if err != nil {
165			return nil, time.Time{}, "", "", err
166		}
167		return &input, start, spanID, traceID, nil
168	}
169	
170	// applySpan stores one validated span in state. Every check that needs the
171	// other spans (parent existence across traces, duplicates, trace id agreement,
172	// time containment) runs here against the state the caller passes, so a batch
173	// sees the spans it has already applied exactly like sequential single-span
174	// ingestion would.
175	func applySpan(state *State, input *SpanInput, start time.Time, spanID string, traceID string) error {
176		spans, found := state.Spans[traceID]
177		if !found {
178			if parentID := input.ParentID; parentID != nil {
179				if _, elsewhere := findSpan(state, *parentID); elsewhere != nil {
180					return ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
181						spanID, traceID, *parentID, *elsewhere)
182				}
183			}
184			spans = map[string]*SpanInput{}
185			state.Spans[traceID] = spans
186		}
187		if _, duplicate := spans[spanID]; duplicate {
188			return ConflictError("span %s already exists in trace %s", spanID, traceID)
189		}
190		resolved, err := lineOf(spans, input)
191		if err != nil {
192			return err
193		}
194		if resolved != traceID {
195			return ConflictError("span %s belongs to trace %s but its parent chain resolves to trace %s",
196				spanID, traceID, resolved)
197		}
198		if input.ParentID != nil {
199			parent, found := spans[*input.ParentID]
200			if found {
201				parentStart, _ := parseTime(parent.StartTime, "start_time")
202				parentEnd := parentStart.Add(time.Duration(parent.DurationNS))
203				end := start.Add(time.Duration(input.DurationNS))
204				if start.Before(parentStart) || end.After(parentEnd) {
205					return ConflictError("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
206						spanID, formatTime(start), formatTime(end), parent.SpanID, parent.StartTime, formatTime(parentEnd))
207				}
208			}
209		}
210		clone := *input
211		clone.Attributes = map[string]string{}
212		for attribute, value := range input.Attributes {
213			clone.Attributes[attribute] = value
214		}
215		spans[spanID] = &clone
216		return nil
217	}
218	
219	// IngestSpan validates and stores one span. Every check that needs the other
220	// spans of the trace (parent existence, trace id agreement, time containment)
221	// runs against the committed state under the store lock.
222	func (s *Service) IngestSpan(body []byte, key string) (any, error) {
223		input, start, spanID, traceID, err := decodeSpanInput(body)
224		if err != nil {
225			return nil, err
226		}
227		operation := "ingest-span"
228		identity := traceID + "/" + spanID
229	
230		if _, err := s.runIdempotent(key, operation, identity, func(state *State) (any, error) {
231			return nil, applySpan(state, input, start, spanID, traceID)
232		}); err != nil {
233			return nil, err
234		}
235		return s.store.View(func(state *State) (any, error) {
236			return renderSpan(state, traceID, spanID)
237		})
238	}
239	
240	// batchItem is one entry of the accepted array of a batch response. Complete,
241	// Valid and Violations snapshot the reassembly of the item's trace as it was
242	// right after that span landed.
243	type batchItem struct {
244		TraceID    string       `json:"trace_id"`
245		SpanID     string       `json:"span_id"`
246		Accepted   bool         `json:"accepted"`
247		Complete   bool         `json:"complete"`
248		Valid      bool         `json:"valid"`
249		Violations []Validation `json:"violations"`
250	}
251	
252	// batchResponse is the body of a successful POST /spans/batch.
253	type batchResponse struct {
254		Accepted []*batchItem `json:"accepted"`
255		Count    int          `json:"count"`
256	}
257	
258	// batchEnvelope is the request body of POST /spans/batch: nothing but the
259	// spans array. Each element stays raw so the spans are decoded and checked one
260	// by one in request order.
261	type batchEnvelope struct {
262		Spans []json.RawMessage `json:"spans"`
263	}
264	
265	// IngestSpanBatch validates and stores a whole batch atomically. The spans are
266	// applied in request order with exactly the rules of single-span ingestion; the
267	// first failure aborts the batch, nothing is committed and the idempotency key
268	// stays unused. A replay with the same key and a byte-identical body returns
269	// the stored first response, because the per-item reassembly snapshots cannot
270	// be re-rendered once later writes have changed the traces.
271	func (s *Service) IngestSpanBatch(body []byte, key string) (any, error) {
272		if err := validateIdempotencyKey(key); err != nil {
273			return nil, err
274		}
275		var envelope batchEnvelope
276		if err := decodeObject(body, &envelope); err != nil {
277			return nil, err
278		}
279		if len(envelope.Spans) == 0 {
280			return nil, ValidationError("spans must contain at least 1 span")
281		}
282		if len(envelope.Spans) > maxBatchSpans {
283			return nil, ValidationError("spans must contain at most %d spans", maxBatchSpans)
284		}
285		operation := "ingest-span-batch"
286		identity := fmt.Sprintf("batch:%x", sha256.Sum256(body))
287	
288		var response any
289		err := s.store.Update(func(state *State) error {
290			if record, found := state.Idempotency[key]; found {
291				if record.Operation != operation {
292					return ConflictError("idempotency key was already used for another operation")
293				}
294				if record.Identity != identity {
295					return ConflictError("idempotency key was already used for a different batch")
296				}
297				response = record.Response
298				return nil
299			}
300			result := &batchResponse{Accepted: []*batchItem{}}
301			for _, raw := range envelope.Spans {
302				input, start, spanID, traceID, err := decodeSpanInput(raw)
303				if err != nil {
304					return err
305				}
306				if err := applySpan(state, input, start, spanID, traceID); err != nil {
307					return err
308				}
309				trace := assembleTrace(traceID, state.Spans[traceID])
310				result.Accepted = append(result.Accepted, &batchItem{
311					TraceID:    traceID,
312					SpanID:     spanID,
313					Accepted:   true,
314					Complete:   trace.Complete,
315					Valid:      trace.Valid,
316					Violations: publicViolations(trace.Violations),
317				})
318			}
319			result.Count = len(result.Accepted)
320			snapshot, err := json.Marshal(result)
321			if err != nil {
322				return InternalError("batch response could not be serialised: %s", err)
323			}
324			state.Idempotency[key] = &IdempotencyRecord{
325				Key:       key,
326				Operation: operation,
327				Identity:  identity,
328				CreatedAt: s.now(),
329				Response:  snapshot,
330			}
331			response = result
332			return nil
333		})
334		if err != nil {
335			return nil, err
336		}
337		return response, nil
338	}
339	
340	// retentionRequest is the body of POST /traces/retention: nothing but the
341	// before instant.
342	type retentionRequest struct {
343		Before string `json:"before"`
344	}
345	
346	// RetentionResult is the body of a successful POST /traces/retention. Before
347	// echoes the cut-off in the canonical UTC layout; the four counts partition
348	// every stored trace and span into deleted and retained.
349	type RetentionResult struct {
350		Before         string `json:"before"`
351		DeletedTraces  int    `json:"deleted_traces"`
352		DeletedSpans   int    `json:"deleted_spans"`
353		RetainedTraces int    `json:"retained_traces"`
354		RetainedSpans  int    `json:"retained_spans"`
355	}
356	
357	// ApplyRetention deletes every trace whose root starts strictly before the
358	// cut-off, together with all of its spans. A trace without a root span has no
359	// knowable start time and is always retained, as is a trace whose root starts
360	// exactly at the cut-off. The operation is not idempotency-keyed: it is a pure
361	// function of the committed state, so repeating the same request on the same
362	// state yields the same result, and the store's copy-on-write commit keeps a
363	// failed persist from changing anything.
364	func (s *Service) ApplyRetention(body []byte) (any, error) {
365		var request retentionRequest
366		if err := decodeObject(body, &request); err != nil {
367			return nil, err
368		}
369		before, err := parseTime(request.Before, "before")
370		if err != nil {
371			return nil, err
372		}
373		result := &RetentionResult{Before: formatTime(before)}
374		err = s.store.Update(func(state *State) error {
375			for _, traceID := range state.traceIDs() {
376				spans := state.Spans[traceID]
377				trace := assembleTrace(traceID, spans)
378				expired := false
379				if trace.Root != nil {
380					if rootStart, err := parseTime(trace.Root.StartTime, "start_time"); err == nil {
381						expired = rootStart.Before(before)
382					}
383				}
384				if expired {
385					result.DeletedTraces++
386					result.DeletedSpans += len(spans)
387					delete(state.Spans, traceID)
388				} else {
389					result.RetainedTraces++
390					result.RetainedSpans += len(spans)
391				}
392			}
393			return nil
394		})
395		if err != nil {
396			return nil, err
397		}
398		return result, nil
399	}
400	
401	// findSpan locates a span id in any trace and returns its trace id.
402	func findSpan(state *State, spanID string) (*SpanInput, *string) {
403		for traceID, spans := range state.Spans {
404			if span, found := spans[spanID]; found {
405				id := traceID
406				return span, &id
407			}
408		}
409		return nil, nil
410	}
411	
412	func publicViolations(violations []Violation) []Validation {
413		public := make([]Validation, 0, len(violations))
414		for _, violation := range violations {
415			public = append(public, Validation{
416				Code:    violation.Code,
417				TraceID: violation.TraceID,
418				SpanID:  violation.SpanID,
419				Message: violation.Message,
420			})
421		}
422		return public
423	}
424	
425	// GetTrace reassembles one trace and fails when it is incomplete or unusable.
426	func (s *Service) GetTrace(traceID string) (any, error) {
427		value, err := s.store.View(func(state *State) (any, error) {
428			spans, found := state.Spans[traceID]
429			if !found {
430				return nil, NotFoundError("trace %s does not exist", traceID)
431			}
432			return assembleTrace(traceID, spans), nil
433		})
434		if err != nil {
435			return nil, err
436		}
437		trace := value.(*Trace)
438		if !trace.Complete {
439			return nil, InvalidTraceError(traceID, append([]Violation{{
440				Code:    "trace_incomplete",
441				TraceID: traceID,
442				SpanID:  "",
443				Message: "trace is not complete yet or its declared span_count does not match the ingested spans",
444			}}, trace.Violations...))
445		}
446		if !trace.Valid {
447			return nil, InvalidTraceError(traceID, trace.Violations)
448		}
449		return trace, nil
450	}
451	
452	// TraceFilter narrows GET /traces. Every condition that is set must hold; a
453	// zero-valued filter keeps every trace. Time and duration fields are present as
454	// pointers so that an unset bound never accidentally matches as zero.
455	type TraceFilter struct {
456		// Query is matched as a Unicode case-insensitive substring of the trace id
457		// or of any span service or operation.
458		Query string
459		// Operation keeps traces that have at least one span with this exact op.
460		Operation string
461		// Service keeps traces that contain this service (the legacy semantics).
462		Service string
463		// Status is "", "error" (at least one error span) or "ok" (no error span).
464		Status string
465		// StartFrom is inclusive and StartTo is exclusive on the root start time.
466		StartFrom *time.Time
467		StartTo   *time.Time
468		// MinDurationNS and MaxDurationNS are both inclusive on the root duration.
469		MinDurationNS *int64
470		MaxDurationNS *int64
471		// Complete and Valid filter on the current reassembly result; nil = unset.
472		Complete *bool
473		Valid    *bool
474		// ServicePath is an ordered chain of two or more service names. A trace
475		// matches when it holds spans s1..sn, each a direct child of the previous
476		// one, whose services equal the chain element by element. Nil means unset.
477		ServicePath []string
478	}
479	
480	// TraceFilterFromQuery parses and validates every documented GET /traces
481	// parameter apart from limit, which the HTTP layer keeps. Unknown parameters
482	// are rejected before this is called. All failures are validation errors.
483	func TraceFilterFromQuery(query url.Values) (*TraceFilter, error) {
484		filter := &TraceFilter{
485			Query:   query.Get("q"),
486			Service: strings.TrimSpace(query.Get("service")),
487		}
488		if raw, present := query.Get("operation"), query.Has("operation"); present {
489			operation := strings.TrimSpace(raw)
490			if operation == "" {
491				return nil, ValidationError("operation must not be empty")
492			}
493			filter.Operation = operation
494		}
495		if query.Has("status") {
496			status := query.Get("status")
497			if status != "ok" && status != "error" {
498				return nil, ValidationError("status must be ok or error")
499			}
500			filter.Status = status
501		}
502		if raw, present := query.Get("start_from"), query.Has("start_from"); present {
503			instant, err := parseTime(raw, "start_from")
504			if err != nil {
505				return nil, err
506			}
507			filter.StartFrom = &instant
508		}
509		if raw, present := query.Get("start_to"), query.Has("start_to"); present {
510			instant, err := parseTime(raw, "start_to")
511			if err != nil {
512				return nil, err
513			}
514			filter.StartTo = &instant
515		}
516		if raw, present := query.Get("min_duration_ns"), query.Has("min_duration_ns"); present {
517			value, err := parseDurationBound(raw, "min_duration_ns")
518			if err != nil {
519				return nil, err
520			}
521			filter.MinDurationNS = &value
522		}
523		if raw, present := query.Get("max_duration_ns"), query.Has("max_duration_ns"); present {
524			value, err := parseDurationBound(raw, "max_duration_ns")
525			if err != nil {
526				return nil, err
527			}
528			filter.MaxDurationNS = &value
529		}
530		if filter.MinDurationNS != nil && filter.MaxDurationNS != nil &&
531			*filter.MinDurationNS > *filter.MaxDurationNS {
532			return nil, ValidationError("min_duration_ns must not be greater than max_duration_ns")
533		}
534		if raw, present := query.Get("complete"), query.Has("complete"); present {
535			value, err := parseBoolean(raw, "complete")
536			if err != nil {
537				return nil, err
538			}
539			filter.Complete = &value
540		}
541		if raw, present := query.Get("valid"), query.Has("valid"); present {
542			value, err := parseBoolean(raw, "valid")
543			if err != nil {
544				return nil, err
545			}
546			filter.Valid = &value
547		}
548		if query.Has("service_path") {
549			path, err := parseServicePath(query["service_path"])
550			if err != nil {
551				return nil, err
552			}
553			filter.ServicePath = path
554		}
555		return filter, nil
556	}
557	
558	const (
559		// maxServicePathItems bounds the number of service_path elements and
560		// maxServicePathName the length of each name.
561		maxServicePathItems = 32
562		maxServicePathName  = 128
563	)
564	
565	// parseServicePath validates the repeated service_path parameter. Names are
566	// kept verbatim because matching is exact, so no whitespace is trimmed.
567	func parseServicePath(names []string) ([]string, error) {
568		if len(names) < 2 || len(names) > maxServicePathItems {
569			return nil, ValidationError("service_path must contain between 2 and %d service names", maxServicePathItems)
570		}
571		for index, name := range names {
572			if name == "" {
573				return nil, ValidationError("service_path names must not be empty")
574			}
575			if len(name) > maxServicePathName {
576				return nil, ValidationError("service_path names must be at most %d characters", maxServicePathName)
577			}
578			if index > 0 && names[index-1] == name {
579				return nil, ValidationError("service_path names must differ from their neighbour")
580			}
581		}
582		return names, nil
583	}
584	
585	// parseDurationBound accepts a decimal non-negative integer with no sign,
586	// exponent or surrounding space.
587	func parseDurationBound(raw string, field string) (int64, error) {
588		if raw == "" || strings.TrimSpace(raw) == "" {
589			return 0, ValidationError("%s must be a decimal non-negative integer", field)
590		}
591		for _, r := range raw {
592			if r < '0' || r > '9' {
593				return 0, ValidationError("%s must be a decimal non-negative integer", field)
594			}
595		}
596		value, err := strconv.ParseInt(raw, 10, 64)
597		if err != nil {
598			return 0, ValidationError("%s must be a decimal non-negative integer", field)
599		}
600		return value, nil
601	}
602	
603	// parseBoolean accepts exactly "true" or "false".
604	func parseBoolean(raw string, field string) (bool, error) {
605		switch raw {
606		case "true":
607			return true, nil
608		case "false":
609			return false, nil
610		default:
611			return false, ValidationError("%s must be true or false", field)
612		}
613	}
614	
615	// matches reports whether one reassembled trace satisfies every set condition.
616	func (f *TraceFilter) matches(trace *Trace) bool {
617		if f.Service != "" {
618			found := false
619			for _, node := range trace.Spans {
620				if node.Service == f.Service {
621					found = true
622					break
623				}
624			}
625			if !found {
626				return false
627			}
628		}
629		if f.Operation != "" {
630			found := false
631			for _, node := range trace.Spans {
632				if node.Operation == f.Operation {
633					found = true
634					break
635				}
636			}
637			if !found {
638				return false
639			}
640		}
641		if f.Query != "" {
642			if !containsFold(trace.TraceID, f.Query) {
643				found := false
644				for _, node := range trace.Spans {
645					if containsFold(node.Service, f.Query) || containsFold(node.Operation, f.Query) {
646						found = true
647						break
648					}
649				}
650				if !found {
651					return false
652				}
653			}
654		}
655		switch f.Status {
656		case "error":
657			if trace.ErrorSpans == 0 {
658				return false
659			}
660		case "ok":
661			if trace.ErrorSpans != 0 {
662				return false
663			}
664		}
665		if f.Complete != nil && trace.Complete != *f.Complete {
666			return false
667		}
668		if f.Valid != nil && trace.Valid != *f.Valid {
669			return false
670		}
671		if len(f.ServicePath) > 0 && !matchServicePath(trace.Spans, f.ServicePath) {
672			return false
673		}
674		if f.StartFrom != nil || f.StartTo != nil || f.MinDurationNS != nil || f.MaxDurationNS != nil {
675			// Every time and duration bound refers to the root. A trace without a
676			// root has neither a root instant nor a root duration, so any such
677			// bound excludes it.
678			if trace.Root == nil {
679				return false
680			}
681		}
682		if f.StartFrom != nil || f.StartTo != nil {
683			rootStart, err := parseTime(trace.Root.StartTime, "start_time")
684			if err != nil {
685				return false
686			}
687			if f.StartFrom != nil && rootStart.Before(*f.StartFrom) {
688				return false
689			}
690			if f.StartTo != nil && !rootStart.Before(*f.StartTo) {
691				return false
692			}
693		}
694		if f.MinDurationNS != nil && trace.DurationNS < *f.MinDurationNS {
695			return false
696		}
697		if f.MaxDurationNS != nil && trace.DurationNS > *f.MaxDurationNS {
698			return false
699		}
700		return true
701	}
702	
703	// matchServicePath reports whether the reassembled span tree contains a chain
704	// of direct parent/child spans whose services equal path element by element.
705	// The chain may start at any span; only the stored parent/child links are
706	// consulted, so an incomplete or invalid trace is judged on the spans it has.
707	func matchServicePath(nodes []*TraceNode, path []string) bool {
708		for _, node := range nodes {
709			if matchServicePathFrom(node, path, 0) {
710				return true
711			}
712		}
713		return false
714	}
715	
716	func matchServicePathFrom(node *TraceNode, path []string, index int) bool {
717		if node.Service != path[index] {
718			return false
719		}
720		if index == len(path)-1 {
721			return true
722		}
723		for _, child := range node.Children {
724			if matchServicePathFrom(child, path, index+1) {
725				return true
726			}
727		}
728		return false
729	}
730	
731	// ListTraces summarises every stored trace with at least one span.
732	func (s *Service) ListTraces(filter *TraceFilter, limit int) (any, error) {
733		if limit < 1 || limit > 400 {
734			return nil, ValidationError("limit must be between 1 and 400")
735		}
736		if filter == nil {
737			filter = &TraceFilter{}
738		}
739		value, err := s.store.View(func(state *State) (any, error) {
740			summaries := []*TraceSummary{}
741			for _, traceID := range state.traceIDs() {
742				trace := assembleTrace(traceID, state.Spans[traceID])
743				if !filter.matches(trace) {
744					continue
745				}
746				summary := &TraceSummary{
747					TraceID:      trace.TraceID,
748					StartTime:    "",
749					DurationNS:   trace.DurationNS,
750					SpanCount:    trace.SpanCount,
751					ServiceCount: trace.ServiceCount,
752					ErrorSpans:   trace.ErrorSpans,
753					Complete:     trace.Complete,
754					Valid:        trace.Valid,
755				}
756				if trace.Root != nil {
757					rootID := trace.Root.SpanID
758					rootService := trace.Root.Service
759					summary.RootSpanID = &rootID
760					summary.RootService = &rootService
761					summary.StartTime = trace.Root.StartTime
762					summary.rootInstant, _ = parseTime(trace.Root.StartTime, "start_time")
763				}
764				summaries = append(summaries, summary)
765			}
766			sort.Slice(summaries, func(i, j int) bool {
767				if !summaries[i].rootInstant.Equal(summaries[j].rootInstant) {
768					return summaries[i].rootInstant.After(summaries[j].rootInstant)
769				}
770				return summaries[i].TraceID < summaries[j].TraceID
771			})
772			if len(summaries) > limit {
773				summaries = summaries[:limit]
774			}
775			return map[string]any{"traces": summaries}, nil
776		})
777		if err != nil {
778			return nil, err
779		}
780		return value, nil
781	}
782	
783	// CriticalPath walks the root-to-leaf path with the largest total self_time. It
784	// therefore needs time containment to hold, exactly like the invariant
785	// "critical path length equals the root span duration" does.
786	func (s *Service) CriticalPath(traceID string) (any, error) {
787		value, err := s.store.View(func(state *State) (any, error) {
788			spans, found := state.Spans[traceID]
789			if !found {
790				return nil, NotFoundError("trace %s does not exist", traceID)
791			}
792			return assembleTrace(traceID, spans), nil
793		})
794		if err != nil {
795			return nil, err
796		}
797		trace := value.(*Trace)
798		path := &CriticalPath{
799			TraceID:         traceID,
800			Method:          "longest chain below the root, weighted by self_time_ns; ties are broken by the longest sub-chain and then by the smallest span id sequence",
801			TraceDurationNS: trace.DurationNS,
802			Path:            []PathStep{},
803			Complete:        trace.Complete,
804			Valid:           trace.Valid || trace.Root == nil,
805			Violations:      publicViolations(trace.Violations),
806		}
807		if !trace.Complete {
808			path.Valid = false
809		}
810		if trace.Root == nil {
811			return path, nil
812		}
813		_, steps := longestSelfTimePath(trace.Root)
814		path.Path = steps
815		for _, step := range steps {
816			path.LengthNS += step.SelfTimeNS
817		}
818		return path, nil
819	}
820	
821	type pathCandidate struct {
822		// weight is the sum of self_time along the candidate: the value the response
823		// reports as the length of the path.
824		weight int64
825		// path is the longest self_time-weighted path of the subtree, used to break a
826		// tie between two branches that weigh the same.
827		path  int64
828		steps int
829		ids   []string
830	}
831	
832	// better ranks two candidates of the same node. More self_time wins. An equal
833	// weight is settled by the branch with the longer critical path, then by the
834	// shorter path, then by the lexicographically smallest span id sequence, so the
835	// output is deterministic.
836	func better(candidate pathCandidate, incumbent pathCandidate) bool {
837		if candidate.weight != incumbent.weight {
838			return candidate.weight > incumbent.weight
839		}
840		if candidate.path != incumbent.path {
841			return candidate.path > incumbent.path
842		}
843		if candidate.steps != incumbent.steps {
844			return candidate.steps < incumbent.steps
845		}
846		for index := 0; index < len(candidate.ids) && index < len(incumbent.ids); index++ {
847			if candidate.ids[index] != incumbent.ids[index] {
848				return candidate.ids[index] < incumbent.ids[index]
849			}
850		}
851		return len(candidate.ids) < len(incumbent.ids)
852	}
853	
854	// longestSelfTimePath returns the winning candidate of the subtree together
855	// with the steps of the critical path, both in pre-order. The tree builder has
856	// already computed maxPath for every span, so the winner is the child whose
857	// maxPath is the largest and the weight of the result is this node's maxPath.
858	func longestSelfTimePath(node *TraceNode) (pathCandidate, []PathStep) {
859		self := PathStep{
860			SpanID:     node.SpanID,
861			ParentID:   node.ParentID,
862			Service:    node.Service,
863			Operation:  node.Operation,
864			Depth:      node.Depth,
865			SelfTimeNS: node.SelfTimeNS,
866			StartTime:  node.StartTime,
867			EndTime:    node.EndTime,
868		}
869		best := pathCandidate{weight: node.SelfTimeNS, path: node.maxPath, steps: 1, ids: []string{node.SpanID}}
870		var bestSteps []PathStep
871		for _, child := range node.Children {
872			candidate, steps := longestSelfTimePath(child)
873			candidate.weight += node.SelfTimeNS
874			candidate.steps++
875			candidate.ids = append([]string{node.SpanID}, candidate.ids...)
876			if bestSteps == nil || better(candidate, best) {
877				best = candidate
878				bestSteps = steps
879			}
880		}
881		if bestSteps == nil {
882			bestSteps = []PathStep{}
883		}
884		steps := append([]PathStep{self}, bestSteps...)
885		weight := int64(0)
886		for _, item := range steps {
887			weight += item.SelfTimeNS
888		}
889		best.weight = weight
890		if best.weight < node.maxPath {
891			best.weight = node.maxPath
892		}
893		return best, steps
894	}
895	
896	// ServiceGraph aggregates the caller/callee graph. traceID limits the analysis
897	// to one trace; an empty traceID covers every stored trace.
898	func (s *Service) ServiceGraph(traceID string) (any, error) {
899		value, err := s.store.View(func(state *State) (any, error) {
900			graph := &ServiceGraph{
901				Services: []*ServiceStat{},
902				Edges:    []*ServiceEdge{},
903				Stats:    &GraphStats{},
904			}
905			ids := state.traceIDs()
906			if traceID != "" {
907				if _, found := state.Spans[traceID]; !found {
908					return nil, NotFoundError("trace %s does not exist", traceID)
909				}
910				ids = []string{traceID}
911				// The response always echoes an explicitly requested trace.
912				graph.TraceID = &ids[0]
913			}
914			services := map[string]*ServiceStat{}
915			edges := map[string]*ServiceEdge{}
916			graph.Stats.durations = []int64{}
917			for _, id := range ids {
918				trace := assembleTrace(id, state.Spans[id])
919				usable := trace.Valid && trace.Complete && trace.Root != nil
920				if !usable {
921					if traceID != "" {
922						// An explicitly requested trace is reported as-is, complete
923						// or not.
924						graph.Stats.PartialTraces = 1
925						return graph, nil
926					}
927					graph.Stats.PartialTraces++
928					continue
929				}
930				graph.Stats.TraceCount++
931				graph.Stats.SpanCount += trace.SpanCount
932				graph.Stats.ErrorSpans += trace.ErrorSpans
933				graph.Stats.durations = append(graph.Stats.durations, trace.DurationNS)
934				for _, node := range trace.Spans {
935					stat := services[node.Service]
936					if stat == nil {
937						stat = &ServiceStat{Service: node.Service, Operations: []*OperationStat{}, durations: []int64{}}
938						services[node.Service] = stat
939					}
940					stat.SpanCount++
941					stat.SelfTimeNS += node.SelfTimeNS
942					stat.durations = append(stat.durations, node.DurationNS)
943					if node.Error {
944						stat.ErrorSpans++
945					}
946					if node.ParentID == nil {
947						stat.RootSpans++
948					}
949					operation := operationStat(stat, node.Operation)
950					operation.SpanCount++
951					operation.SelfTimeNS += node.SelfTimeNS
952					operation.durations = append(operation.durations, node.DurationNS)
953					if node.Error {
954						operation.ErrorSpans++
955					}
956				}
957				byID := map[string]*TraceNode{}
958				for _, node := range trace.Spans {
959					byID[node.SpanID] = node
960				}
961				for _, node := range trace.Spans {
962					if node.ParentID == nil {
963						continue
964					}
965					parent := byID[*node.ParentID]
966					if parent == nil || parent.Service == node.Service {
967						continue
968					}
969					key := parent.Service + "\x00" + node.Service
970					edge := edges[key]
971					if edge == nil {
972						edge = &ServiceEdge{Caller: parent.Service, Callee: node.Service, durations: []int64{}}
973						edges[key] = edge
974					}
975					edge.CallCount++
976					edge.durations = append(edge.durations, node.DurationNS)
977					if node.Error {
978						edge.ErrorCount++
979					}
980				}
981			}
982			for _, stat := range services {
983				finalizeService(stat)
984				graph.Services = append(graph.Services, stat)
985			}
986			for _, edge := range edges {
987				finalizeEdge(edge)
988				graph.Edges = append(graph.Edges, edge)
989			}
990			sort.Slice(graph.Services, func(i, j int) bool { return graph.Services[i].Service < graph.Services[j].Service })
991			sort.Slice(graph.Edges, func(i, j int) bool {
992				if graph.Edges[i].Caller != graph.Edges[j].Caller {
993					return graph.Edges[i].Caller < graph.Edges[j].Caller
994				}
995				return graph.Edges[i].Callee < graph.Edges[j].Callee
996			})
997			finalizeStats(graph.Stats)
998			return graph, nil
999		})
1000		if err != nil {
1001			return nil, err
1002		}
1003		return value, nil
1004	}
1005	
1006	func operationStat(service *ServiceStat, operation string) *OperationStat {
1007		for _, stat := range service.Operations {
1008			if stat.Operation == operation {
1009				return stat
1010			}
1011		}
1012		stat := &OperationStat{Operation: operation, durations: []int64{}}
1013		service.Operations = append(service.Operations, stat)
1014		return stat
1015	}
1016	
1017	func finalizeService(stat *ServiceStat) {
1018		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
1019		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
1020		stat.MeanDurationNS = mean(stat.durations)
1021		stat.P50DurationNS = percentile(stat.durations, 50)
1022		stat.P95DurationNS = percentile(stat.durations, 95)
1023		stat.durations = nil
1024		sort.Slice(stat.Operations, func(i, j int) bool { return stat.Operations[i].Operation < stat.Operations[j].Operation })
1025		for _, operation := range stat.Operations {
1026			finalizeOperation(operation)
1027		}
1028	}
1029	
1030	func finalizeOperation(stat *OperationStat) {
1031		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
1032		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
1033		stat.MeanDurationNS = mean(stat.durations)
1034		stat.P50DurationNS = percentile(stat.durations, 50)
1035		stat.P95DurationNS = percentile(stat.durations, 95)
1036		stat.durations = nil
1037	}
1038	
1039	func finalizeEdge(edge *ServiceEdge) {
1040		sort.Slice(edge.durations, func(i, j int) bool { return edge.durations[i] < edge.durations[j] })
1041		edge.MinDurationNS, edge.MaxDurationNS = bounds(edge.durations)
1042		edge.MeanDurationNS = mean(edge.durations)
1043		edge.P50DurationNS = percentile(edge.durations, 50)
1044		edge.P95DurationNS = percentile(edge.durations, 95)
1045		edge.durations = nil
1046	}
1047	
1048	func finalizeStats(stats *GraphStats) {
1049		sort.Slice(stats.durations, func(i, j int) bool { return stats.durations[i] < stats.durations[j] })
1050		stats.DurationNS, _ = bounds(stats.durations)
1051		stats.MeanDurationNS = mean(stats.durations)
1052		stats.P50DurationNS = percentile(stats.durations, 50)
1053		stats.P95DurationNS = percentile(stats.durations, 95)
1054		stats.durations = nil
1055	}
1056	
1057	func bounds(sorted []int64) (int64, int64) {
1058		if len(sorted) == 0 {
1059			return 0, 0
1060		}
1061		return sorted[0], sorted[len(sorted)-1]
1062	}
1063	
1064	func mean(sorted []int64) int64 {
1065		if len(sorted) == 0 {
1066			return 0
1067		}
1068		total := int64(0)
1069		for _, value := range sorted {
1070			total += value
1071		}
1072		return total / int64(len(sorted))
1073	}
1074	
1075	// percentile uses the nearest-rank definition on already sorted input:
1076	// index = ceil(p/100 * n) - 1. Input is never mutated.
1077	func percentile(sorted []int64, p int) int64 {
1078		if len(sorted) == 0 {
1079			return 0
1080		}
1081		rank := (p*len(sorted) + 99) / 100
1082		if rank < 1 {
1083			rank = 1
1084		}
1085		if rank > len(sorted) {
1086			rank = len(sorted)
1087		}
1088		return sorted[rank-1]
1089	}
1090	
1091	func sortStrings(values []string) {
1092		sort.Strings(values)
1093	}
1094

