291	// parseTime accepts an RFC3339 timestamp with optional fractional seconds.
292	func parseTime(value string, field string) (time.Time, error) {
293		if strings.TrimSpace(value) == "" {
294			return time.Time{}, ValidationError("%s is required", field)
295		}
296		instant, err := time.Parse(time.RFC3339Nano, value)
297		if err != nil {
298			return time.Time{}, ValidationError("%s must be an RFC3339 timestamp", field)
299		}
300		return instant.UTC(), nil
301	}
302	
303	// containsFold reports whether text contains needle under Unicode simple case
304	// folding, the substring analogue of strings.EqualFold. Runes are compared by
305	// walking the complete SimpleFold equivalence cycle, the same rule
306	// strings.EqualFold applies at one rune position.
307	func containsFold(text string, needle string) bool {
308		if needle == "" {
309			return true
310		}
311		haystack := []rune(text)
312		target := []rune(needle)
313		if len(target) > len(haystack) {
314			return false
315		}
316		for start := 0; start <= len(haystack)-len(target); start++ {
317			matches := true
318			for offset := range target {
319				if !runesEqualFold(haystack[start+offset], target[offset]) {
320					matches = false
321					break
322				}
323			}
324			if matches {
325				return true
326			}
327		}
328		return false
329	}
330	
331	// runesEqualFold reports whether two runes are simple-case-fold equivalent.
332	func runesEqualFold(left rune, right rune) bool {
333		if left == right {
334			return true
335		}
336		for r := unicode.SimpleFold(left); r != left; r = unicode.SimpleFold(r) {
337			if r == right {
338				return true
339			}
340		}
341		return false
342	}
