357		if trimmed == "" {
358			return "", ValidationError("%s is required", field)
359		}
360		if len(trimmed) > maxTextLength {
361			return "", ValidationError("%s must be at most %d characters", field, maxTextLength)
362		}
363		return trimmed, nil
364	}
