101		case method == http.MethodGet && len(parts) == 2 && parts[0] == "services" && parts[1] == "graph":
102			if err := requireQuery(request, "trace_id"); err != nil {
103				return 0, nil, err
104			}
105			response, err := s.service.ServiceGraph(strings.TrimSpace(request.URL.Query().Get("trace_id")))
106			return http.StatusOK, response, err
