111	func readJSONBody(request *http.Request) ([]byte, error) {
112		contentType := request.Header.Get("Content-Type")
113		mediaType, _, _ := strings.Cut(contentType, ";")
114		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
115			return nil, ValidationError("Content-Type must be application/json")
116		}
117		body, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
118		if err != nil {
119			return nil, ValidationError("request body could not be read")
120		}
121		if len(body) > maxBodyBytes {
122			return nil, ValidationError("request body must be at most %d bytes", maxBodyBytes)
123		}
124		return body, nil
125	}
