127	func splitPath(path string) []string {
128		parts := []string{}
129		for _, part := range strings.Split(path, "/") {
130			if part != "" {
131				parts = append(parts, part)
132			}
133		}
134		return parts
135	}
136	
137	// requireQuery rejects every query parameter that the route does not document.
138	func requireQuery(request *http.Request, allowed ...string) error {
139		names := make([]string, 0, len(request.URL.Query()))
140		for name := range request.URL.Query() {
